WITH enriched AS (SELECT id, country, FIRST_VALUE(browser) IGNORE NULLS OVER w_ordered AS first_known_browser, FIRST_VALUE(country) IGNORE NULLS OVER w_ordered AS first_known_country FROM sessions WHERE device = 'mobile' WINDOW w_ordered AS (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, first_known_browser, first_known_country FROM enriched;
